#include <vector>
#include <numeric>

class Solution {
public:
    std::vector<bool> friendRequests(int n, std::vector<std::vector<int>>& restrictions, std::vector<std::vector<int>>& requests) {
        std::vector<int> parent(n);
        std::iota(parent.begin(), parent.end(), 0);

        auto find = [&](auto& self, int i) -> int {
            if (parent[i] != i) parent[i] = self(self, parent[i]);
            return parent[i];
        };

        std::vector<bool> res;
        res.reserve(requests.size());

        for (const auto& req : requests) {
            int ru = find(find, req[0]);
            int rv = find(find, req[1]);
            if (ru == rv) {
                res.push_back(true);
                continue;
            }

            bool valid = true;
            for (const auto& rest : restrictions) {
                int rx = find(find, rest[0]);
                int ry = find(find, rest[1]);
                if ((rx == ru && ry == rv) || (rx == rv && ry == ru)) {
                    valid = false;
                    break;
                }
            }

            if (valid) {
                parent[ru] = rv;
                res.push_back(true);
            } else {
                res.push_back(false);
            }
        }
        return res;
    }
};

import java.util.ArrayList;
import java.util.List;

class Solution {
    public boolean[] friendRequests(int n, int[][] restrictions, int[][] requests) {
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        boolean[] res = new boolean[requests.length];
        for (int i = 0; i < requests.length; i++) {
            int ru = find(requests[i][0], parent);
            int rv = find(requests[i][1], parent);
            if (ru == rv) {
                res[i] = true;
                continue;
            }

            boolean valid = true;
            for (int[] rest : restrictions) {
                int rx = find(rest[0], parent);
                int ry = find(rest[1], parent);
                if ((rx == ru && ry == rv) || (rx == rv && ry == ru)) {
                    valid = false;
                    break;
                }
            }

            if (valid) {
                parent[ru] = rv;
                res[i] = true;
            } else {
                res[i] = false;
            }
        }
        return res;
    }

    private int find(int i, int[] parent) {
        if (parent[i] != i) parent[i] = find(parent[i], parent);
        return parent[i];
    }
}

/**
 * @param {number} n
 * @param {number[][]} restrictions
 * @param {number[][]} requests
 * @return {boolean[]}
 */
var friendRequests = function(n, restrictions, requests) {
    const parent = Array.from({ length: n }, (_, i) => i);

    function find(i) {
        if (parent[i] !== i) parent[i] = find(parent[i]);
        return parent[i];
    }

    const res = [];
    for (const [u, v] of requests) {
        const ru = find(u);
        const rv = find(v);
        if (ru === rv) {
            res.push(true);
            continue;
        }

        let valid = true;
        for (const [x, y] of restrictions) {
            const rx = find(x);
            const ry = find(y);
            if ((rx === ru && ry === rv) || (rx === rv && ry === ru)) {
                valid = false;
                break;
            }
        }

        if (valid) {
            parent[ru] = rv;
            res.push(true);
        } else {
            res.push(false);
        }
    }
    return res;
};
